ALTER TABLE molecules 
  ADD COLUMN wikidata_qid VARCHAR(20) NULL COMMENT 'Wikidata QID (e.g. Q193178 for linalool)',
  ADD COLUMN wikidata_enriched_at TIMESTAMP NULL COMMENT 'When Wikidata data was fetched';

ALTER TABLE plants 
  ADD COLUMN wikidata_qid VARCHAR(20) NULL COMMENT 'Wikidata QID (e.g. Q193178 for Rosa damascena)',
  ADD COLUMN wikidata_enriched_at TIMESTAMP NULL COMMENT 'When Wikidata data was fetched';
